require_once dirname(__DIR__,3).'/bootstrap.php';$allowedRoles=[ROLE_SECURITY];require APP_ROOT.'/app/middleware/RoleMiddleware.php';use App\Services\VisitorService;use PhpOffice\PhpSpreadsheet\IOFactory;
$errors=[];$success=0;if(isset($_GET['download_template'])){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="visitor_import_template.csv"');$out=fopen('php://output','w');fputcsv($out,['VisitorName','StudentId','Phone','Purpose','IdType','IdNumber']);fputcsv($out,['John Doe','STUDENT_ID','0800000000','Visit','National ID','ID001']);fclose($out);exit;}if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='import_visitors'&&!empty($_FILES['visitors_file'])){$file=$_FILES['visitors_file'];$extension=strtolower(pathinfo($file['name']??'',PATHINFO_EXTENSION));if($file['error']!==UPLOAD_ERR_OK||!in_array($extension,['csv','xlsx'],true)){$errors[]='Upload a valid CSV or XLSX file.';}else{try{$rows=IOFactory::load($file['tmp_name'])->getActiveSheet()->toArray(null,true,true,false);$header=array_map(fn($v)=>strtolower(preg_replace('/[^a-z0-9]/i','',(string)$v)),array_shift($rows)?:[]);$map=[];foreach($header as $i=>$name)$map[$name]=$i;foreach(array_slice($rows,0,1000) as $row){$value=fn($name,$fallback=-1)=>$row[$map[strtolower(preg_replace('/[^a-z0-9]/i','',$name))]??$fallback]??'';$name=sanitize($value('visitorname',0));$student=sanitize($value('studentid',1));if($name===''||$student==='')continue;$result=(new VisitorService())->register(['visitorName'=>$name,'studentId'=>$student,'phone'=>sanitize($value('phone',2)),'purpose'=>sanitize($value('purpose',3)),'idType'=>sanitize($value('idtype',4)),'idNumber'=>sanitize($value('idnumber',5)),'registeredBy'=>current_user()['uid']??current_user()['id']??null]);if(!empty($result['success']))$success++;}flash('success',"Imported {$success} visitor(s).");redirect(url('views/security/visitors/bulk-import.php'));}catch(Throwable $e){$errors[]='Import failed: '.$e->getMessage();}}}$pageTitle='Bulk Visitor Import';$navItems=[['icon'=>'bi-people','label'=>'Visitors','href'=>url('views/security/visitors/visitors.php')],['icon'=>'bi-upload','label'=>'Import Visitors','href'=>url('views/security/visitors/bulk-import.php'),'active'=>true]];require APP_ROOT.'/app/views/components/header.php';require APP_ROOT.'/app/views/components/sidebar.php';?>
<div class="main-content"><?php require APP_ROOT.'/app/views/components/navbar.php';?><?php require APP_ROOT.'/app/views/components/alerts.php';?><div class="content-wrapper"><div class="card stat-card p-4" style="max-width:760px"><h5 class="mb-3">Import Visitors</h5><?php foreach($errors as $error):?><div class="alert alert-danger"><?=e($error)?></div><?php endforeach;?><form method="POST" enctype="multipart/form-data"><input type="hidden" name="action" value="import_visitors"><label class="form-label">CSV or XLSX file</label><input type="file" name="visitors_file" class="form-control mb-3" accept=".csv,.xlsx" required><p class="small text-muted">Headers: VisitorName, StudentId, Phone, Purpose, IdType, IdNumber. Maximum 1,000 rows.</p><button class="btn btn-primary">Upload and import</button> <a class="btn btn-outline-secondary" href="<?=url('views/security/visitors/bulk-import.php?download_template=1')?>">Download template</a></form></div></div></div><?php require APP_ROOT.'/app/views/components/footer.php';?>